  html = html.replace(/href="\.\.\/documents\//g,'href="documents/').replace(/href="\.\.\/\.\.\/nghien_cuu_quy_trinh\//g,'href="../nghien_cuu_quy_trinh/').replace(/href="\.\.\/reports\//g,'href="reports/');
