    if(level==='1') return `<h2 class="report-title">${label}</h2>`;
    const key = `${id}-${label.replace(/<[^>]*>/g,'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replaceAll('đ','d').toLowerCase().replace(/[^a-z0-9]+/g,'-')}`;
    const count = (used.get(key)||0)+1; used.set(key,count);
